<?php require_once 'includes/db.php'; $pageTitle='Painel'; require 'includes/header.php';
$counts=[]; foreach(['produtos','enderecos','transportadores','fretes'] as $t){$counts[$t]=(int)$pdo->query("SELECT COUNT(*) FROM $t")->fetchColumn();}
$recent=$pdo->query("SELECT f.id,f.codigo,f.data_frete,f.status,t.nome transportador FROM fretes f JOIN transportadores t ON t.id=f.transportador_id ORDER BY f.id DESC LIMIT 5")->fetchAll(); ?>
<div class="page-heading"><div><h1 class="h3 mb-1">Visão geral</h1><p class="text-secondary mb-0">Acompanhe os cadastros e operações logísticas.</p></div><a class="btn btn-primary" href="frete_form.php">+ Novo frete</a></div>
<div class="row g-3 mb-4"><?php foreach(['produtos'=>'Produtos','enderecos'=>'Endereços','transportadores'=>'Transportadores','fretes'=>'Fretes'] as $key=>$label): ?><div class="col-6 col-lg-3"><div class="card p-3"><div class="text-secondary"><?=e($label)?></div><div class="stat"><?=$counts[$key]?></div></div></div><?php endforeach; ?></div>
<div class="card p-3"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h5 mb-0">Fretes recentes</h2><a href="fretes.php">Ver todos</a></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Código</th><th>Data</th><th>Transportador</th><th>Status</th></tr></thead><tbody><?php if(!$recent): ?><tr><td colspan="4" class="text-center text-secondary py-4">Nenhum frete cadastrado.</td></tr><?php endif; foreach($recent as $r): ?><tr><td><?=e($r['codigo'])?></td><td><?=date('d/m/Y',strtotime($r['data_frete']))?></td><td><?=e($r['transportador'])?></td><td><span class="badge text-bg-<?= $r['status']==='Concluído'?'success':'warning' ?>"><?=e($r['status'])?></span></td></tr><?php endforeach; ?></tbody></table></div></div>
